      addSec("routes", "Entry routes", "the entry routes", `${routeRows.length} on file — the front door is ${clause(s(r0.route))}${detail ? ` — ${clause(detail)}` : ""}${others.length ? `; also on file: ${others.map(clause).join("; ")}` : ""}${flag}`);
