    const firstCells = splitCsvLine(lines[0]);
    const isHeader = firstCells && firstCells.some((c) => HEADER_ALIASES[norm(c)] === "full_name")
      && firstCells.some((c) => HEADER_ALIASES[norm(c)] === "current_firm");
